uth_example:
import math

def sigmoid(z):
    return 1 / (1 + math.exp(-z))

spam_scores = {"win money now": 4.2, "meeting at 3": -1.7, "free trial ends": 0.4}
threshold = 0.5

decisions = {}
for subject, score in spam_scores.items():
    p = round(sigmoid(score), 3)
    decisions[subject] = {"p_spam": p, "spam": p >= threshold}

print("sigmoid(0) =", sigmoid(0))
for subject, d in decisions.items():
    print(f"{subject:16} {d}")
